mapper.sql:
FROM promotions_recommend_like_items r_items LEFT JOIN items ON r_items.item_id = items.item_id
INNER JOIN distribution_distributor_items d_items ON r_items.item_id = d_items.item_id AND d_items.distributor_id = #{distributorId}
WHERE r_items.company_id = #{companyId}
AND d_items.is_can_sale = 1
AND items.approve_status = 'onsale'
